import { PWAConfig as ImportedPWAConfig } from '../types';

export function generateServiceWorker(config: ImportedPWAConfig): string {
  return `
// Service Worker for ${config.name}
// Generated by Recoder.xyz PWA Builder

const CACHE_NAME = '${config.shortName.toLowerCase()}-v1';
const STATIC_CACHE = '${config.shortName.toLowerCase()}-static-v1';
const DYNAMIC_CACHE = '${config.shortName.toLowerCase()}-dynamic-v1';

// Assets to precache
const PRECACHE_ASSETS = [
  '/',
  '/manifest.json',
  '/css/pwa-styles.css',
  '/js/pwa-utils.js',
  ${config.serviceWorker.precachePatterns.map(pattern => `'${pattern}'`).join(',\n  ')}
];

// Install event - cache static assets
self.addEventListener('install', (event) => {
  console.log('Service Worker: Installing...');
  
  event.waitUntil(
    caches.open(STATIC_CACHE)
      .then(cache => {
        console.log('Service Worker: Precaching static assets');
        return cache.addAll(PRECACHE_ASSETS);
      })
      .then(() => {
        ${config.serviceWorker.skipWaiting ? 'return self.skipWaiting();' : 'console.log("Service Worker: Installed");'}
      })
      .catch(error => {
        console.error('Service Worker: Precaching failed', error);
      })
  );
});

// Activate event - clean up old caches
self.addEventListener('activate', (event) => {
  console.log('Service Worker: Activating...');
  
  event.waitUntil(
    caches.keys()
      .then(cacheNames => {
        return Promise.all(
          cacheNames.map(cacheName => {
            if (cacheName !== CACHE_NAME && cacheName !== STATIC_CACHE && cacheName !== DYNAMIC_CACHE) {
              console.log('Service Worker: Deleting old cache', cacheName);
              return caches.delete(cacheName);
            }
          })
        );
      })
      .then(() => {
        ${config.serviceWorker.clientsClaim ? 'return self.clients.claim();' : 'console.log("Service Worker: Activated");'}
      })
  );
});

// Fetch event - implement caching strategy
self.addEventListener('fetch', (event) => {
  const { request } = event;
  const url = new URL(request.url);
  
  // Skip non-GET requests
  if (request.method !== 'GET') {
    return;
  }
  
  // Skip external requests
  if (url.origin !== location.origin) {
    return;
  }

  ${generateCachingStrategy(config)}
});

${config.features.backgroundSync ? generateBackgroundSync(config) : ''}

${config.features.pushNotifications ? generatePushHandler(config) : ''}

${config.offline.enabled ? generateOfflineHandler(config) : ''}

// Helper function to determine caching strategy
function getCachingStrategy(url) {
  ${config.serviceWorker.runtimeCaching.map(rule => `
  if (${rule.urlPattern.startsWith('/') ? `url.pathname.match(/${rule.urlPattern.replace(/\//g, '\\/')}/)`  : `url.href.match(/${rule.urlPattern}/)`}) {
    return {
      strategy: '${rule.handler}',
      cacheName: '${rule.options.cacheName || `${config.shortName.toLowerCase()}-${rule.handler.toLowerCase()}`}',
      options: ${JSON.stringify(rule.options)}
    };
  }`).join('\n  ')}
  
  // Default strategy
  return {
    strategy: '${config.caching.strategy === 'cache-first' ? 'CacheFirst' : config.caching.strategy === 'network-first' ? 'NetworkFirst' : 'StaleWhileRevalidate'}',
    cacheName: DYNAMIC_CACHE,
    options: {
      expiration: {
        maxEntries: ${config.caching.maxCacheSize},
        maxAgeSeconds: ${config.caching.maxAge}
      }
    }
  };
}

// Cache management utilities
async function cleanupCache(cacheName, maxEntries, maxAge) {
  const cache = await caches.open(cacheName);
  const keys = await cache.keys();
  
  // Remove expired entries
  if (maxAge) {
    const now = Date.now();
    for (const request of keys) {
      const response = await cache.match(request);
      if (response) {
        const dateHeader = response.headers.get('date');
        if (dateHeader) {
          const responseTime = new Date(dateHeader).getTime();
          if (now - responseTime > maxAge * 1000) {
            await cache.delete(request);
          }
        }
      }
    }
  }
  
  // Remove excess entries
  if (maxEntries && keys.length > maxEntries) {
    const sortedKeys = keys.sort((a, b) => {
      // Sort by last accessed (simplified)
      return a.url.localeCompare(b.url);
    });
    
    const keysToDelete = sortedKeys.slice(maxEntries);
    for (const key of keysToDelete) {
      await cache.delete(key);
    }
  }
}

// Update notification
function showUpdateNotification() {
  self.registration.showNotification('${config.name} Updated', {
    body: 'A new version is available. Restart the app to update.',
    icon: '${config.notifications.defaultIcon}',
    badge: '${config.notifications.defaultBadge}',
    tag: 'app-update',
    requireInteraction: true,
    actions: [
      {
        action: 'update',
        title: 'Update Now'
      },
      {
        action: 'dismiss',
        title: 'Later'
      }
    ]
  });
}

// Handle notification clicks
self.addEventListener('notificationclick', (event) => {
  event.notification.close();
  
  if (event.action === 'update') {
    // Reload all clients
    self.clients.matchAll().then(clients => {
      clients.forEach(client => {
        client.postMessage({ type: 'RELOAD_APP' });
      });
    });
  }
});
`;
}

function generateCachingStrategy(config: ImportedPWAConfig): string {
  const strategy = config.caching.strategy;
  
  if (strategy === 'cache-first') {
    return `
  event.respondWith(
    caches.match(request)
      .then(response => {
        if (response) {
          return response;
        }
        
        return fetch(request)
          .then(fetchResponse => {
            const responseClone = fetchResponse.clone();
            const strategy = getCachingStrategy(url);
            
            caches.open(strategy.cacheName)
              .then(cache => {
                cache.put(request, responseClone);
              });
            
            return fetchResponse;
          });
      })
      .catch(() => {
        // Return offline fallback
        if (request.destination === 'document') {
          return caches.match('${config.offline.fallbackPage}');
        }
      })
  );`;
  } else if (strategy === 'network-first') {
    return `
  event.respondWith(
    fetch(request)
      .then(response => {
        const responseClone = response.clone();
        const strategy = getCachingStrategy(url);
        
        caches.open(strategy.cacheName)
          .then(cache => {
            cache.put(request, responseClone);
          });
        
        return response;
      })
      .catch(() => {
        return caches.match(request)
          .then(response => {
            if (response) {
              return response;
            }
            
            // Return offline fallback
            if (request.destination === 'document') {
              return caches.match('${config.offline.fallbackPage}');
            }
          });
      })
  );`;
  } else {
    return `
  event.respondWith(
    caches.match(request)
      .then(response => {
        const fetchPromise = fetch(request)
          .then(fetchResponse => {
            const responseClone = fetchResponse.clone();
            const strategy = getCachingStrategy(url);
            
            caches.open(strategy.cacheName)
              .then(cache => {
                cache.put(request, responseClone);
              });
            
            return fetchResponse;
          });
        
        return response || fetchPromise;
      })
      .catch(() => {
        // Return offline fallback
        if (request.destination === 'document') {
          return caches.match('${config.offline.fallbackPage}');
        }
      })
  );`;
  }
}

function generateBackgroundSync(config: ImportedPWAConfig): string {
  return `
// Background Sync
self.addEventListener('sync', (event) => {
  console.log('Service Worker: Background sync triggered', event.tag);
  
  if (event.tag === 'background-sync') {
    event.waitUntil(doBackgroundSync());
  } else if (event.tag === 'offline-data-sync') {
    event.waitUntil(syncOfflineData());
  }
});

async function doBackgroundSync() {
  try {
    // Get pending sync items from IndexedDB
    const pendingItems = await getPendingSyncItems();
    
    for (const item of pendingItems) {
      try {
        const response = await fetch(item.url, {
          method: item.method || 'POST',
          headers: {
            'Content-Type': 'application/json',
            ...item.headers
          },
          body: JSON.stringify(item.data)
        });
        
        if (response.ok) {
          await removeSyncItem(item.id);
          console.log('Background sync: Item synced successfully', item.id);
        } else {
          throw new Error(\`Sync failed: \${response.status}\`);
        }
      } catch (error) {
        console.error('Background sync: Failed to sync item', item.id, error);
        await incrementRetryCount(item.id);
      }
    }
  } catch (error) {
    console.error('Background sync: Failed', error);
  }
}

async function syncOfflineData() {
  try {
    const offlineData = await getOfflineData();
    
    const response = await fetch('${config.notifications.subscriberEndpoint.replace('/subscribe', '/sync')}', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json'
      },
      body: JSON.stringify({
        action: 'sync-offline-data',
        data: offlineData
      })
    });
    
    if (response.ok) {
      await clearOfflineData();
      console.log('Background sync: Offline data synced');
    }
  } catch (error) {
    console.error('Background sync: Offline data sync failed', error);
  }
}

// IndexedDB helpers for background sync
async function getPendingSyncItems() {
  // This would integrate with the IndexedDB implementation
  return [];
}

async function removeSyncItem(id) {
  // Remove synced item from IndexedDB
}

async function incrementRetryCount(id) {
  // Increment retry count for failed sync item
}

async function getOfflineData() {
  // Get offline data from IndexedDB
  return [];
}

async function clearOfflineData() {
  // Clear synced offline data
}`;
}

function generatePushHandler(config: ImportedPWAConfig): string {
  return `
// Push Notifications
self.addEventListener('push', (event) => {
  console.log('Service Worker: Push notification received');
  
  let notificationData = {
    title: '${config.name}',
    body: 'You have a new notification',
    icon: '${config.notifications.defaultIcon}',
    badge: '${config.notifications.defaultBadge}',
    tag: 'default',
    requireInteraction: false,
    actions: []
  };
  
  if (event.data) {
    try {
      const data = event.data.json();
      notificationData = { ...notificationData, ...data };
    } catch (error) {
      console.error('Service Worker: Failed to parse push data', error);
      notificationData.body = event.data.text();
    }
  }
  
  event.waitUntil(
    self.registration.showNotification(notificationData.title, notificationData)
      .then(() => {
        console.log('Service Worker: Notification shown');
        
        // Track notification display
        return fetch('/api/analytics', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            event: 'notification_displayed',
            data: {
              tag: notificationData.tag,
              timestamp: Date.now()
            }
          })
        }).catch(() => {}); // Ignore analytics errors
      })
  );
});

// Handle notification clicks
self.addEventListener('notificationclick', (event) => {
  console.log('Service Worker: Notification clicked');
  
  event.notification.close();
  
  // Track notification click
  fetch('/api/analytics', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      event: 'notification_clicked',
      data: {
        tag: event.notification.tag,
        action: event.action,
        timestamp: Date.now()
      }
    })
  }).catch(() => {}); // Ignore analytics errors
  
  // Handle notification action
  if (event.action) {
    switch (event.action) {
      case 'open':
      case 'view':
        event.waitUntil(
          clients.openWindow(event.notification.data?.url || '/')
        );
        break;
      case 'dismiss':
        // Just close the notification
        break;
      default:
        console.log('Unknown notification action:', event.action);
    }
  } else {
    // Default action - open the app
    event.waitUntil(
      clients.matchAll({ type: 'window', includeUncontrolled: true })
        .then(clientList => {
          // Check if app is already open
          for (const client of clientList) {
            if (client.url.includes(self.location.origin) && 'focus' in client) {
              return client.focus();
            }
          }
          
          // Open new window
          if (clients.openWindow) {
            return clients.openWindow(event.notification.data?.url || '/');
          }
        })
    );
  }
});`;
}

function generateOfflineHandler(config: ImportedPWAConfig): string {
  return `
// Offline handling
self.addEventListener('fetch', (event) => {
  // Handle offline scenarios
  if (!navigator.onLine) {
    console.log('Service Worker: Device is offline');
    
    // For API requests, queue them for background sync
    if (event.request.url.includes('/api/') && event.request.method === 'POST') {
      event.respondWith(
        queueForBackgroundSync(event.request)
          .then(() => {
            return new Response(JSON.stringify({
              success: true,
              message: 'Request queued for background sync',
              offline: true
            }), {
              headers: { 'Content-Type': 'application/json' },
              status: 202
            });
          })
      );
      return;
    }
  }
});

async function queueForBackgroundSync(request) {
  try {
    const body = await request.text();
    const syncItem = {
      url: request.url,
      method: request.method,
      headers: Object.fromEntries(request.headers.entries()),
      body: body,
      timestamp: Date.now(),
      retryCount: 0
    };
    
    // Store in IndexedDB for background sync
    await storeSyncItem(syncItem);
    
    // Register background sync
    if ('serviceWorker' in navigator && 'sync' in window.ServiceWorkerRegistration.prototype) {
      return self.registration.sync.register('background-sync');
    }
  } catch (error) {
    console.error('Service Worker: Failed to queue for background sync', error);
    throw error;
  }
}

async function storeSyncItem(item) {
  // This would integrate with IndexedDB
  console.log('Service Worker: Storing sync item', item);
}`;
}

export interface PWAConfig {
  name: string;
  shortName: string;
  description: string;
  themeColor: string;
  backgroundColor: string;
  display: 'standalone' | 'fullscreen' | 'minimal-ui' | 'browser';
  orientation: 'any' | 'natural' | 'landscape' | 'portrait';
  startUrl: string;
  scope: string;
  icons: Array<{
    src: string;
    sizes: string;
    type: string;
    purpose?: 'any' | 'maskable' | 'monochrome';
  }>;
  serviceWorker: {
    enabled: boolean;
    fileName: string;
    workboxVersion: string;
    runtimeCaching: Array<{
      urlPattern: string;
      handler: string;
      options: any;
    }>;
    precachePatterns: string[];
    skipWaiting: boolean;
    clientsClaim: boolean;
  };
  features: {
    installPrompt: boolean;
    offlineSupport: boolean;
    backgroundSync: boolean;
    pushNotifications: boolean;
    fileSystemAccess: boolean;
    cameraAccess: boolean;
    geolocation: boolean;
    webShare: boolean;
    deviceVibration: boolean;
    screenWakeLock: boolean;
  };
  caching: {
    strategy: string;
    maxCacheSize: number;
    maxAge: number;
    excludePatterns: string[];
    includePatterns: string[];
  };
  offline: {
    enabled: boolean;
    fallbackPage: string;
    offlineAssets: string[];
    indexedDBEnabled: boolean;
    conflictResolution: string;
  };
  notifications: {
    enabled: boolean;
    vapidKeys: {
      publicKey: string;
      privateKey: string;
    };
    subscriberEndpoint: string;
    defaultIcon: string;
    defaultBadge: string;
  };
}
